/* tools/oars_loader/style.css
 * CSS for the footer DATA chip + OARS viewer dialog + boot overlay
 * lives in the kernel CSS today; migrated here in Phase 3c.
 * Empty for Phase 3a — kernel CSS still owns the rules during the
 * parallel-installation test window, so the tool's chip + viewer use
 * the same visual styles as the kernel's. */


/* ─── Status pill + viewer dialog (moved from taskpane_v3.css 1635-1716, 1741-1842 in Batch 5D 2026-05-11) ───
 * Status pill family (._eli3_status_data*) renders the footer DATA chip
 * (loaded ⚡ / processing ⏳ / empty 📂). Viewer dialog (._eli3_oars_viewer_*)
 * shows the loaded OARS file in a tabbed read-only viewer. Both ship with
 * the bundle so deploys without OARS skip the CSS too.
 *
 * .status-data* aliases preserved for v2-installed users on the same kernel
 * (kernel CSS aliasing rule). ._eli3_dialog_resize_grip stays in the kernel
 * — it is a generic primitive any resizable dialog can reuse. */
.status-data,
._eli3_status_data {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: var(--font-sm);
}
/* The pill is just a flex container — no border, no padding. The BOX
   is on the icon only (and only for the loaded/processing states). */
._eli3_status_data_pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  cursor: pointer;
  line-height: 1.3;
}

/* Status icon — ALL states */
._eli3_status_data_icon {
  font-size: 14px;
  line-height: 1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}
/* Loaded → ⚡ in an amber-bordered box */
._eli3_status_data_icon_loaded {
  cursor: pointer;
  color: #f59e0b;
  border: 1px solid rgba(245,158,11,0.5);
  background: rgba(245,158,11,0.08);
  border-radius: 3px;
  padding: 1px 5px;
  filter: drop-shadow(0 1px 2px rgba(245,158,11,0.4));
}
._eli3_status_data_icon_loaded:hover {
  color: #fbbf24;
  border-color: #f59e0b;
  background: rgba(245,158,11,0.15);
}
/* Processing → ⏳ in a blue-bordered box (pulses) */
._eli3_status_data_icon_processing {
  color: var(--color-blue);
  border: 1px solid rgba(21,101,192,0.4);
  background: rgba(21,101,192,0.06);
  border-radius: 3px;
  padding: 1px 5px;
  animation: _eli3_oars_processing_pulse 1.2s ease-in-out infinite;
}
@keyframes _eli3_oars_processing_pulse {
  0%, 100% { opacity: 0.55; }
  50%      { opacity: 1; }
}
/* Empty → 📂 no box, plain icon */
._eli3_status_data_icon_empty {
  color: var(--text-dim);
  opacity: 0.85;
}

/* Text — never boxed */
.status-data-label,
._eli3_status_data_label,
._eli3_status_data_text {
  font-weight: var(--weight-bold);
  color: var(--text-status-footer);
}
.status-data-text--loaded,
._eli3_status_data_text_loaded {
  color: var(--color-green-deep);
}

/* Clear ✕ — outside the pill, right */
.status-data-clear,
._eli3_status_data_clear {
  cursor: pointer;
  color: var(--text-dim);
  font-weight: var(--weight-extrabold);
  padding: 0 var(--space-1);
  font-size: 13px;
}
.status-data-clear:hover,
._eli3_status_data_clear:hover { color: var(--color-red); }

/* OARS data viewer — minimal premium. Dialog header (kernel-rendered)
   already says "OARS Data Viewer"; we DON'T duplicate. The body is just:
     [tabs row with filename on the right] → [scrolling panel].
   Two surfaces, one accent (gold key column), pure typography.

   Built dark-first per CSS layering convention going forward: dark
   mode is the default; light mode is the override. */
._eli3_oars_viewer_dialog .eli-dialog-desc { text-align: left; padding: 0; }

/* ── Tabs row ─────────────────────────────────────────────────────── */
._eli3_oars_viewer_tabs {
  display: flex;
  margin: 4px -8px 0;
  padding: 0 22px;
  background: #f9fafb;
  border-bottom: 1px solid #e2e8f0;
  gap: 16px;
}
._eli3_oars_viewer_tab {
  padding: 12px 4px;
  margin-right: 18px;
  cursor: pointer;
  background: transparent;
  border: none;
  border-bottom: 2px solid transparent;
  font: 700 11px/1 'Inter', sans-serif;
  text-transform: uppercase; letter-spacing: 0.7px;
  color: #475569;
  transition: color 0.15s, border-color 0.15s;
  margin-bottom: -1px;
}
._eli3_oars_viewer_tab:hover { color: #0f172a; }
._eli3_oars_viewer_tab_active {
  color: #0f172a;
  border-bottom-color: #c9a227;
}

/* ── Scrolling panel ──────────────────────────────────────────────── */
._eli3_oars_viewer_panel {
  max-height: calc(90vh - 200px);
  min-height: 200px;
  overflow-y: auto;
  padding: 14px 22px 18px;
  margin: 0 -8px;
  background: #fff;
}
._eli3_oars_viewer_panel_hidden { display: none; }

/* ── Processed view ───────────────────────────────────────────────── */
._eli3_oars_viewer_grid {
  display: grid;
  grid-template-columns: minmax(160px, 30%) 1fr;
  font-family: 'Inter', system-ui, sans-serif;
  background: #fff;
  border-radius: 6px;
  overflow: hidden;
  box-shadow: 0 0 0 1px #e2e8f0;
}
._eli3_oars_viewer_k,
._eli3_oars_viewer_v {
  padding: 11px 16px;
  line-height: 1.5;
}
._eli3_oars_viewer_grid > ._eli3_oars_viewer_k:nth-child(4n+1),
._eli3_oars_viewer_grid > ._eli3_oars_viewer_v:nth-child(4n+2) {
  background: #f8fafc;
}
._eli3_oars_viewer_k {
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.5px;
  text-transform: uppercase;
  color: #c9a227;
  border-right: 1px solid #e2e8f0;
  align-self: center;
}
._eli3_oars_viewer_v {
  font-size: 13px;
  font-weight: 500;
  color: #0f172a;
  word-break: break-word;
}

/* ── Unprocessed view ─────────────────────────────────────────────── */
._eli3_oars_viewer_pre {
  font: 500 12px/1.6 'JetBrains Mono', 'Consolas', monospace;
  color: #1e293b;
  background: #f8fafc;
  padding: 16px 18px;
  border-radius: 6px;
  box-shadow: 0 0 0 1px #e2e8f0;
  white-space: pre-wrap; word-break: break-word;
  margin: 0;
}

._eli3_oars_viewer_empty {
  text-align: center;
  padding: 48px 24px;
  color: #94a3b8;
  font: 500 13px/1.5 'Inter', sans-serif;
  font-style: italic;
}
